//! 📦️ Original decoder terminal handoff and paid owner return.
use semio_framework_value_native_decoding::*;
use std::mem::size_of;
/// 🔐️ Holds the actual returned decoder owners until their original physical receipt settles.
#[derive(Default)]
pub struct NativeDecodeFrameTerminalOutput{frame:std::mem::ManuallyDrop<Option<NativeDecodeFrame>>,recipient:std::mem::ManuallyDrop<Option<NativeDecodeRetirementRecipient>>,lock:Option<semio_framework_value_control_contract::OriginalConstructionActionIdentity>,settled:bool}
impl NativeDecodeFrameTerminalOutput{
 /// 👁️ Observes completion without exposing an unsettled owner.
 pub fn is_ready(&self)->bool{self.settled&&self.frame.is_some()&&self.recipient.is_some()}
 /// 🫴️ Lends the actual settled owners without moving either header.
 pub fn owners_mut(&mut self)->Result<(&mut NativeDecodeFrame,&mut NativeDecodeRetirementRecipient),ValueError>{if !self.is_ready(){return Err(ValueError::literal(ValueRefusalKind::OwnershipLimit,"terminal decoder output has not settled"))}Ok((self.frame.as_mut().expect("settled frame retained"),self.recipient.as_mut().expect("settled recipient retained")))}
 /// 🧭️ Reads the original bound Source only after physical delivery settles.
 pub fn source_turn(&self)->Option<semio_framework_value_control_contract::OriginalSourceTurnIdentity>{if self.is_ready(){self.frame.as_ref().and_then(|frame|frame.terminal_work_binding().and_then(|binding|binding.source_turn()))}else{None}}
 /// 🪪️ Validates a real Work loan against the delivered original owner.
 pub fn validates_work_loan(&self,loan:&OriginalWorkLoan<'_>)->Result<bool,ValueError>{if !self.is_ready(){return Ok(false)}let frame=self.frame.as_ref().expect("settled frame retained");match frame.terminal_work_binding(){Some(binding)=>binding.validates_loan(loan),None=>Ok(false)}}
 /// 🪪️ Observes the original ledger only after its physical handoff settles.
 pub fn ledger_identity(&self)->Option<crate::NativeAllocationIdentity>{if self.is_ready(){self.frame.as_ref().map(NativeDecodeFrame::ledger_identity)}else{None}}
}
impl Drop for NativeDecodeFrameTerminalOutput{fn drop(&mut self){assert!(std::thread::panicking()||self.frame.is_none()&&self.recipient.is_none()&&self.lock.is_none(),"terminal decoder output requires paid owner return")}}
/// 🔐️ Keeps actual terminal refusal data sealed until its own paid Post settles.
#[derive(Default)]
pub struct NativeTerminalFailureOutput{failure:std::mem::ManuallyDrop<Option<crate::OriginalReceivingPrimary>>,binding:Option<semio_framework_value_control_contract::OriginalWorkBindingIdentity>,lock:Option<semio_framework_value_control_contract::OriginalConstructionActionIdentity>,settled:bool}
impl NativeTerminalFailureOutput{
 /// 👁️ Borrows the original independent causes only after actual settlement.
 pub fn failure(&self)->Option<&crate::OriginalReceivingPrimary>{if self.settled{self.failure.as_ref()}else{None}}
}
impl NativeTerminalFailureOutput{
 /// 📏️ Quotes the exact original physical refusal owner before generic retirement.
 pub fn receipt_completion_release_demand(&self)->Result<Option<RetirementDemand>,ValueError>{if !self.settled{return Err(ValueError::invariant("terminal failure output is unsettled"))}self.failure.as_ref().ok_or_else(||ValueError::invariant("terminal failure output is absent"))?.receipt_completion_release_demand()}
 /// ♻️ Retires the same issuer-owned receipt under the original Work and physical payout.
 pub fn retire_receipt_completion(&mut self,physical:&mut semio_framework_value_control_contract::OriginalConstructionLoan<'_>,payout:&semio_framework_value_control_contract::OriginalConstructionAction,effect:&mut RetainedAllocationEffect<'_>)->RetainedWorkOutcome<Option<RetainedCloneProgress>,ValueError>{let fail=|error|RetainedWorkOutcome{result:Err(error),work:0};if !self.settled||self.binding.is_none_or(|binding|!binding.matches_effect(effect)){return fail(ValueError::literal(ValueRefusalKind::OwnershipLimit,"terminal failure retirement changed its original Work"))}let Some(failure)=self.failure.as_mut()else{return fail(ValueError::invariant("terminal failure output is absent"))};failure.retire_receipt_completion(physical,payout,effect)}
 /// 📏️ Quotes the actual failure and controlled-retirement resident headers.
 pub fn retirement_admission_demand()->crate::RetirementDemand{crate::RetirementDemand{copy_bytes:std::mem::size_of::<Option<Self>>()+std::mem::size_of::<Option<crate::retirement::controlled::ControlledRetirement<Self>>>(),depth:1,..Default::default()}}
 /// 🧹️ Admits the same settled failure into its paid resident controlled retirement.
 pub fn admit_retirement_into<'reply>(source:&mut Option<Self>,retirement:&mut Option<crate::retirement::controlled::ControlledRetirement<Self>>,effect:&mut crate::RetainedAllocationEffect<'_>,reply:crate::OriginalEffectReply<'reply,crate::RetainedCloneStep,crate::OriginalRetirementFailure>)->Result<crate::OriginalEffectReplyComplete<'reply,crate::RetainedCloneStep,crate::OriginalRetirementFailure>,ValueError>{
  if retirement.is_some(){return Ok(reply.complete(Err(ValueError::invariant("terminal failure retirement destination is occupied").into())))}let Some(original)=source.as_ref()else{return Ok(reply.complete(Ok(crate::RetainedCloneStep::Progress(Default::default()))))};if !crate::retirement::RetireOwned::retirement_ready(original)||original.binding.is_none_or(|binding|!binding.matches_effect(effect)){return Ok(reply.complete(Err(ValueError::literal(ValueRefusalKind::OwnershipLimit,"terminal failure retirement requires its original settled Work").into())))}let demand=Self::retirement_admission_demand();if effect.remaining_work_units()?<1||!crate::retained_clone::retained_clone_grant_admits(effect.grant(),demand){return Ok(reply.complete(Ok(crate::RetainedCloneStep::Progress(Default::default()))))}if !effect.performed(1)?{return Ok(reply.complete(Err(ValueError::literal(ValueRefusalKind::WorkLimit,"terminal failure retirement exceeded original Work").into())))}*retirement=Some(crate::retirement::controlled::ControlledRetirement::retain(source.take().expect("original settled terminal failure checked")));Ok(reply.complete(Ok(crate::RetainedCloneStep::Complete(crate::RetainedCloneProgress{copied_items:1,copied_bytes:demand.copy_bytes,..Default::default()}))))
 }
}
impl Drop for NativeTerminalFailureOutput{fn drop(&mut self){assert!(std::thread::panicking()||self.failure.is_none()&&self.binding.is_none()&&self.lock.is_none(),"terminal failure output requires paid original retirement")}}
impl crate::retirement::RetireOwned for NativeTerminalFailureOutput{
 type RetirementCursor=<Option<crate::OriginalReceivingPrimary> as crate::retirement::RetireOwned>::RetirementCursor;
 fn retirement_ready(&self)->bool{self.settled&&self.lock.is_none()&&crate::retirement::RetireOwned::retirement_ready(&*self.failure)}
 fn retirement_seed(mut self)->Self::RetirementCursor{self.settled=false;self.binding=None;crate::retirement::RetireOwned::retirement_seed(self.failure.take())}
 fn retirement_birth_bytes(&self)->Option<usize>{crate::retirement::RetireOwned::retirement_ready(self).then_some(std::mem::size_of::<Self::RetirementCursor>())}
 fn controlled_retirement_supported()->bool{true}
 fn retirement_element_copy_bytes()->usize{std::mem::size_of::<Self>()}
}
